import React from "react";
import FamilyForm from "./components/FamilyForm";
import FamilyList from "./components/FamilyList";

function App() {
    return (
        <div className="container">
            <h1>NutriGen AI</h1>
            <p>Family Meal & Grocery Planner</p>

            <FamilyForm />
            <FamilyList />
        </div>
    );
}

export default App;
